"""Builds db/supabase_setup.sql: everything Supabase needs, as one file to paste into its SQL Editor.
Re-run after changing anything in db/init:  python scripts/build_supabase_sql.py
"""
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
HEADER = """-- Knowledge bank: one-time setup for a NEW Supabase project.
-- GENERATED by scripts/build_supabase_sql.py from db/init; edit those files, not this one.
--
-- 1. Replace CHANGE_ME_APP_PASSWORD below with a long random password (letters and digits).
-- 2. Paste this whole file into Supabase > SQL Editor > New query, and click Run.

CREATE ROLE kb_owner NOLOGIN;
CREATE ROLE kb_app LOGIN PASSWORD 'CHANGE_ME_APP_PASSWORD' NOSUPERUSER NOBYPASSRLS;
GRANT CREATE, USAGE ON SCHEMA public TO kb_owner;
GRANT USAGE ON SCHEMA public TO kb_app;
GRANT kb_owner TO postgres;

"""
FOOTER = """
-- Supabase exposes the public schema through its auto-generated REST API. This app doesn't use
-- that API, so make sure its roles can't reach these tables at all.
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM anon, authenticated;
REVOKE EXECUTE ON FUNCTION kb_current_user() FROM anon, authenticated, PUBLIC;
GRANT EXECUTE ON FUNCTION kb_current_user() TO kb_app;
"""


def build() -> str:
    init = ROOT / "db" / "init"
    return HEADER + (init / "02_schema.sql").read_text() + "\n" + (init / "03_dev_users.sql").read_text() + FOOTER


if __name__ == "__main__":
    (ROOT / "db" / "supabase_setup.sql").write_text(build())
    print("wrote db/supabase_setup.sql")
